def seed_catalogue() -> None:
    """Seed the seven internal tools (BUILD_CONVENTIONS §5) and policy version 1 (idempotent).

    Catalogue changes ship as a new migration that calls this again (same pattern as tenant-service)."""
    from sqlalchemy.dialects.postgresql import insert

    from mcp_registry.catalogue import INTERNAL_TOOLS
    from mcp_registry.policy import DEFAULT_POLICY
    from mcp_registry.tables import ai_policy_versions, tool_definitions

    for tool in INTERNAL_TOOLS:
        values = {**tool, "kind": "internal", "enabled": True}
        op.execute(
            insert(tool_definitions)
            .values(**values)
            .on_conflict_do_update(
                index_elements=["tool_id"],
                set_={k: v for k, v in values.items() if k not in ("tool_id", "enabled")},
            )
        )
    op.execute(
        insert(ai_policy_versions)
        .values(version=1, policy=DEFAULT_POLICY.model_dump(), status="active", deployed_by="system:migration")
        .on_conflict_do_nothing(index_elements=["version"])
    )


